module.exports=[4194,a=>{"use strict";let b=[{slug:"politikalarimiz",label:"Politikalarımız",title:"Politikalarımız",subtitle:"Kalite, çevre ve iş sağlığı ve güvenliği politikalarımız bir arada.",description:"Saniteks kalite, çevre ve iş sağlığı ve güvenliği politikaları: sürekli iyileştirme, sıfır hata, çevreye duyarlı üretim ve güvenli çalışma ortamı.",blocks:[{id:"kalite-politikamiz",navLabel:"Kalite Politikamız",eyebrow:"KALİTE POLİTİKAMIZ",heading:"Sıfır hata, toplam kalite sorumluluğu.",paragraphs:["Saniteks, Sanifoam grubunun kalite politikasını benimser. Tüm çalışanlarımız, doğruyu bulmak için “Sürekli İyileştirme” prensibiyle hareket eder.","Müşteri memnuniyetini ve beklentilerini tümüyle karşılayan ürünler; en ekonomik şartlarda, “Sıfır Hata” ilkesiyle, sürekli ve güvenilir kalitede üretilir.","Tüm faaliyetlerimiz “Toplam Kalite Sorumluluğu” bilinciyle sürdürülür ve geliştirilir."],principlesTitle:"Temel ilkeler",principles:["Sürekli iyileştirme prensibi","Sıfır hata ilkesi","Toplam kalite sorumluluğu","Müşteri beklentisine uygun üretim"]},{id:"cevre-politikamiz",navLabel:"Çevre Politikamız",eyebrow:"ÇEVRE POLİTİKAMIZ",heading:"Çevreye duyarlı, sürdürülebilir üretim.",paragraphs:["Saniteks, Sanifoam grubunun Çevre Politikası doğrultusunda çevre üzerinde oluşabilecek olumsuz etkileri azaltmayı ve önlemeyi hedefler. Ulusal ve uluslararası yasal düzenlemelere, çevreyle ilgili kanun, mevzuat ve diğer yükümlülüklere eksiksiz uyarız.","Endüstriyel kirliliği kaynağında en aza indirir, atıkları kontrol altında tutup azaltarak geri kazanımı özendirir; doğal kaynak ve enerji tüketimini kontrol altında tutarak kullanımını en aza indiririz.","Düzenlediğimiz eğitimlerle çalışanlarımızın ve tedarikçilerimizin çevre bilincini bir yaşam felsefesi olarak benimsemesini sağlar; çevre amaç ve hedeflerimizi oluşturarak sürekli gelişmeye katkıda bulunuruz."],principlesTitle:"Odak alanları",principles:["Yasal düzenlemelere tam uyum","Atıkların azaltılması ve geri kazanım","Doğal kaynak ve enerji verimliliği","Çalışan ve tedarikçi çevre eğitimleri"]},{id:"isg-politikamiz",navLabel:"İSG Politikamız",eyebrow:"İSG POLİTİKAMIZ",heading:"Önce insan, önce güvenlik.",paragraphs:["Saniteks olarak en değerli varlığımız çalışanlarımızdır. İş Sağlığı ve Güvenliği (İSG) standartlarını yasal mevzuatın ötesinde bir kurum kültürü olarak benimsiyoruz.","Güvenli ve sağlıklı bir çalışma ortamı yaratmak, iş kazalarını sıfıra indirmek ve meslek hastalıklarını önlemek için sürekli eğitimler düzenliyor ve önleyici tedbirler alıyoruz."],principlesTitle:"Önceliklerimiz",principles:["Sıfır iş kazası hedefi","Düzenli personel eğitimleri","Risk değerlendirme yönetimi","Ergonomik ve güvenli çalışma alanları"]}]},{slug:"sikayet-prosedurleri",label:"Şikâyet Prosedürleri",title:"Şikâyet Prosedürleri",subtitle:"Geri bildirimleriniz gelişim fırsatımızdır.",description:"Saniteks ürünleriyle ilgili şikâyet ve geri bildirimlerinizi nasıl iletebileceğinizi ve nasıl değerlendirildiğini öğrenin.",blocks:[{id:"yaklasimimiz",eyebrow:"ŞİKÂYET PROSEDÜRLERİ",heading:"Geri bildirimleriniz gelişim fırsatımızdır.",paragraphs:["Müşteri memnuniyetini en üst düzeyde tutmak amacıyla tüm geri bildirim ve şikâyetleri şeffaf, adil ve hızlı bir şekilde değerlendiriyoruz.","Her şikâyeti süreçlerimizi iyileştirmek için değerli bir fırsat olarak görüyor, çözüm odaklı yaklaşımımızla müşteri güvenini güçlendiriyoruz."],principlesTitle:"Yaklaşımımız",principles:["Hızlı geri dönüş","Kök neden analizi","Şeffaf süreç yönetimi","Müşteri memnuniyeti odaklı çözümler"]}]},{slug:"kalite-belgelerimiz",label:"Kalite Belgelerimiz",title:"Kalite Belgelerimiz",subtitle:"Uluslararası standartlara göre yönetim sistemleri.",description:"Saniteks ürünlerinin üretimine ilişkin kalite, çevre ve iş sağlığı ve güvenliği yönetim sistemi belgeleri.",blocks:[{id:"yonetim-sistemleri",eyebrow:"KALİTE BELGELERİMİZ",heading:"Uluslararası standartlara göre yönetim sistemleri.",paragraphs:["Ürünlerimizin üretimi; kalite (ISO 9001), çevre (ISO 14001) ve iş sağlığı ve güvenliği (ISO 45001) yönetim sistemi standartları çerçevesinde yürütülür.","Belgelerimiz, belgelendirme kuruluşunun belirttiği geçerlilik tarihleriyle birlikte bu sayfada yayımlanır."],principlesTitle:"Yönetim sistemleri",principles:["ISO 9001 Kalite Yönetim Sistemi","ISO 14001 Çevre Yönetim Sistemi","ISO 45001 İSG Yönetim Sistemi"]}]}],c="Sanifoam Endüstri ve Tüketim Ürünleri San. Tic. A.Ş. — Veliköy OSB, Çerkezköy / Tekirdağ",d="Perakende sektörü için bulaşık süngeri ve yer bezi üretimi",e=[{standard:"ISO 9001:2015",title:"Kalite Yönetim Sistemi",number:"203406/C/0001/UK/Tr",issuer:"URS (United Registrar of Systems)",holder:c,scope:d,validFrom:"2022-09-23",validUntil:"2025-09-22",file:"/documents/certificates/iso-9001-2015.pdf"},{standard:"ISO 14001:2015",title:"Çevre Yönetim Sistemi",number:"203406/B/0001/UK/Tr",issuer:"URS (United Registrar of Systems)",holder:c,scope:d,validFrom:"2022-09-19",validUntil:"2025-09-18",file:"/documents/certificates/iso-14001-2015.pdf"},{standard:"ISO 45001:2018",title:"İş Sağlığı ve Güvenliği Yönetim Sistemi",number:"203406/A/0001/UK/Tr",issuer:"URS (United Registrar of Systems)",holder:c,scope:d,validFrom:"2022-09-17",validUntil:"2025-09-16",file:"/documents/certificates/iso-45001-2018.pdf"}];a.s(["d",0,function(a){return new Intl.DateTimeFormat("tr-TR",{day:"numeric",month:"long",year:"numeric",timeZone:"Europe/Istanbul"}).format(new Date(`${a}T12:00:00Z`))},"U",0,function(a){return b.find(b=>b.slug===a)},"J",0,a=>`/kalite/${a}`,"u",0,b,"A",0,function(a=new Date){let b=a.toISOString().slice(0,10);return e.filter(a=>a.validUntil>=b)}])}];

